mapper.select:
SELECT
    COUNT(*)
FROM diary
WHERE member_id = #{memberId}
  AND diary_date = #{diaryDate}
  AND (status IS NULL OR status != 'DELETED')

SELECT d.diary_id, d.trip_id, d.member_id, d.content, d.diary_date, d.visibility, d.status, d.is_ai_generated, d.created_at, d.updated_at FROM diary d
AND (d.status IS NULL OR d.status != 'DELETED')
AND d.member_id = #{memberId}
AND d.trip_id = #{tripId}
AND d.diary_date = #{diaryDate}
AND d.diary_id < #{cursor}
ORDER BY d.diary_id DESC LIMIT #{size}
